}


#ai-config-button .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef329c48e6126bd7d4d5.png') !important;
    background-size: 20px !important;

}

#sys-settings-button .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef329c48e6126bd7d4d7.png') !important;
    background-size: 20px !important;
}

#advanced-formatting-button .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef329c48e6126bd7d4d6.png') !important;
    background-size: 20px !important;
}

#WI-SP-button .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef329c48e6126bd7d4da.png') !important;
    background-size: 20px !important;
}

#amily2_main_drawer .drawer-icon::before,
#table_database_settings_drawer .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef329c48e6126bd7d4d9.png') !important;
