}

#persona-management-button .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef619c48e6126bd7d5a7.png') !important;
    background-size: 20px !important;
}

#rightNavHolder .drawer-icon::before {
    background-image: url('https://pic1.imgdb.cn/item/6976ef619c48e6126bd7d5a6.png') !important;
    background-size: 20px !important;
}

#options_button::before {
    background-image: url('https://pic1.imgdb.cn/item/6976f1539c48e6126bd7dddd.png') !important;
    background-size: 20px !important;
    top: -10px;
